{
  "case_id": "C02",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Hook: zombie cells",
      "narration": "Some cells in your body stop dividing but never quite die. They linger, pumping out inflammatory signals, and they build up as we age. Scientists call them senescent cells.",
      "on_screen": "Animation: dividing cells; one halts, turns grey, and starts emitting signal puffs. Caption: SENESCENT CELLS",
      "claim_refs": ["SYN-C02:background"]
    },
    {
      "beat": "The experiment",
      "narration": "Researchers took ninety-six elderly mice, twenty-four months old, and randomly gave each one either a pair of drugs called dasatinib and quercetin, or a dummy treatment. Three doses every two weeks, for sixteen weeks. The scientists measuring the results didn't know which mice got which.",
      "on_screen": "Split screen: 96 mouse icons splitting into two groups; calendar strip marking 3 dosing days every 14 days across 16 weeks. Caption: RANDOMISED, BLINDED",
      "claim_refs": ["SYN-C02:abstract", "SYN-C02:methods"]
    },
    {
      "beat": "What improved",
      "narration": "In fat tissue, senescent cells dropped by forty-one percent. On a rotating-rod balance test, treated mice hung on twenty-two percent longer. And their median remaining lifespan rose from about twenty-one weeks to nearly twenty-seven.",
      "on_screen": "Three animated stat cards: -41% senescent cells (adipose) - +22% rotarod latency - 21.4 to 26.9 weeks median remaining life",
      "claim_refs": ["SYN-C02:result:p16INK4a burden", "SYN-C02:result:rotarod latency", "SYN-C02:result:median remaining lifespan"]
    },
    {
      "beat": "What didn't",
      "narration": "But grip strength didn't budge at all. The benefit showed up in some measures of physical function, not every one.",
      "on_screen": "Fourth stat card, greyed out: grip strength - no difference (p = 0.62)",
      "claim_refs": ["SYN-C02:result:grip strength"]
    },
    {
      "beat": "The caveats",
      "narration": "And the limits matter. This was mice, not people. One inbred strain, at one age. Senescent cells were counted in fat tissue only, so we don't yet know what happened elsewhere in the body.",
      "on_screen": "Mouse icon with a red 'not human' stamp; body diagram with only the fat depot highlighted. Caption: PRECLINICAL - ONE TISSUE - ONE STRAIN",
      "claim_refs": ["SYN-C02:limitations", "SYN-C02:study_design"]
    },
    {
      "beat": "Why it's watched",
      "narration": "Still, both drugs are already available for other uses, which is why researchers are keen to find out whether any of this carries over to us.",
      "on_screen": "Text card: Both compounds already in clinical use or widely available. Next question: does it translate?",
      "claim_refs": ["SYN-C02:discussion"]
    }
  ]
}
